import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Tree map: what every directory is, and why it exists","description":"","frontmatter":{},"headers":[],"relativePath":"arch/tree-map.md","filePath":"arch/tree-map.md"}'),r={name:"arch/tree-map.md"};function a(s,e,i,n,l,h){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="tree-map-what-every-directory-is-and-why-it-exists" tabindex="-1">Tree map: what every directory is, and why it exists <a class="header-anchor" href="#tree-map-what-every-directory-is-and-why-it-exists" aria-label="Permalink to &quot;Tree map: what every directory is, and why it exists&quot;">​</a></h1><p>A layer-by-layer reading of the repository. Every directory below has a one-paragraph answer to two questions: <strong>what is inside</strong> and <strong>why does it exist</strong>. The system-level view of the four components is <a href="./system-map.html">system-map.md</a>; this page is the file-tree counterpart.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocos/</span></span>\n<span class="line"><span>  Makefile  include/  etc/  evidence/  website/  docs/  tools/  tests/</span></span>\n<span class="line"><span>  .github/  grub.cfg  grub-ab.cfg</span></span>\n<span class="line"><span>  ocbl/   &lt;- boot loader            (BIOS + UEFI flavors)</span></span>\n<span class="line"><span>  ocire/  &lt;- recovery kernel        (independent L0 peer)</span></span>\n<span class="line"><span>  ocse/   &lt;- install environment    (vendored from v1.0.0)</span></span>\n<span class="line"><span>  ocos/   &lt;- the main system        (kernel + drivers + services + L1 apps)</span></span></code></pre></div><h2 id="root-directory" tabindex="-1">Root directory <a class="header-anchor" href="#root-directory" aria-label="Permalink to &quot;Root directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>What it is / why it exists</th></tr></thead><tbody><tr><td><code>Makefile</code></td><td>The WP-13 build composition root. <code>OC_RELEASE_VERSION ?= 3.0.0-NAK</code> (line 90) and <code>OC_KERNEL_BUILD ?= git rev-list --count HEAD + 21</code> (lines 103-104) are the single version source every component consumes (see <a href="./system-map.html">system-map.md</a>). Targets: <code>make</code>/<code>kernel</code> (ELF), <code>all</code> (kernel + ISO + src zip + OTA), <code>iso</code>, <code>run-bios</code>/<code>run-uefi</code>/<code>shot-*</code>, <code>reproducible-check</code>, <code>dist</code>, <code>clean</code>. Includes the per-component makefiles in dependency order: <code>ocire/ocire.mk</code> -&gt; <code>ocbl/ocbl.mk</code> -&gt; <code>ocse/ocse.mk</code>. Also carries the <code>ARCH</code> dispatch (<code>x86_64</code> default; <code>arm64</code>/<code>riscv</code> build the bring-up shells only).</td></tr><tr><td><code>ARCHITECTURE.md</code></td><td>The root architecture statement: the two rings (L0 provides services / L1 uses services), component inventory, pointers to <code>docs/data/stats.json</code> (regenerated by <code>make api-docs</code>).</td></tr><tr><td><code>README.md</code>, <code>BUILDING.md</code>, <code>CONTRIBUTING.md</code>, <code>FAQ.md</code></td><td>The standard front-door documents (also mirrored under <code>docs/root/</code>).</td></tr><tr><td><code>INTERFACES.md</code></td><td>The historical interface register (numbered L1 extension surface 1-138 era); the live ring-3 contract is <code>ocos/interface/</code> (<a href="./private-headers.html">private-headers.md</a>).</td></tr><tr><td><code>KNOWN_ISSUES.md</code></td><td>Declared, deliberate limitations (e.g. &quot;#DF panic is minimal by design&quot;).</td></tr><tr><td><code>bug-list.md</code></td><td>The 3.0.0 defect census: 141 GitHub issues + the WP-06h audit findings, exported for the fix work packages.</td></tr><tr><td><code>VERIFICATION_REPORT.md</code>, <code>MANIFEST.md</code>, <code>ARCHIVE-README.md</code></td><td>Release evidence: verification transcript, shipped-file manifest, and the pointer readme for archived material.</td></tr><tr><td><code>LICENSE</code>, <code>NOTICE</code></td><td>Apache-2.0 text and attribution notice.</td></tr><tr><td><code>build.ps1</code></td><td>Windows PowerShell build wrapper (the primary path is the Makefile).</td></tr><tr><td><code>grub.cfg</code></td><td>The <strong>removable/ISO medium</strong> GRUB menu (pre-OCBL era, still shipped for GRUB-booted media): loads the gfxterm/font/serial module stack, implements the A/B flag selection on <code>(hd0)</code>, offers slot A/B/ISO entries, attaches the kernel ELF as the <code>self</code> module.</td></tr><tr><td><code>grub-ab.cfg</code></td><td>The <strong>installed A/B disk</strong> variant of the same selection logic - minimal (no gfxterm, no ISO fallback), refreshed by every update install as <code>/boot/grub/grub.cfg</code> on partition 1. Two files exist because the two media have different needs, but both implement byte-identical <code>next_B</code>/<code>bootfail_B</code>/<code>ok_B</code> flag semantics - the same contract OCBL&#39;s native scanner implements (the third implementation). GRUB itself left the release ISO in 3.0.0-WP05 B5-7; it survives as the legacy disk contract and as the in-kernel embedded boot data for the <code>install</code>/<code>abdisk</code>/<code>grub-install</code> commands (<code>tools/embed_grub.py</code>).</td></tr><tr><td><code>include/</code></td><td>Exactly one file: <code>ocbl_state.h</code> - the freestanding WP07a boot-state contract shared byte-for-byte by OCBL, OCOS and OCIRE (magic numbers, stage enum, <code>ocst_state_t</code>/<code>ocst_record_t</code> layouts, budgets). It sits at the repo root because three top-level trees include it and none of them may own it.</td></tr><tr><td><code>etc/</code></td><td>Host-side configuration inputs baked into images: <code>opencube.conf</code> (the default <code>/etc/opencube.conf</code>: update_url, auto_check, package_url, log.level, serial_encoding, pmtimer.width...) and <code>i18n/l0/{en,zh}.json</code> - the L0-side i18n tables that <code>tools/gen_l0_i18n.py</code> compiles into <code>ocos/kernel/core_lib_i18n_data.c</code>.</td></tr><tr><td><code>evidence/</code></td><td>Frozen acceptance transcripts: <code>help_a_runtime.txt</code> (the full <code>help -a</code> registry listing captured live) and <code>v1_command_list.txt</code> (the v1.0.0 command inventory kept for parity checks).</td></tr><tr><td><code>website/</code></td><td>The project site (<code>index.html</code>, <code>about.html</code>, <code>architecture.html</code>, <code>download.html</code>, assets, CNAME) plus <code>public/downloads/</code> - the update artifacts the in-OS <code>checkupdate</code> actually fetches, and <code>public/update.json</code> / <code>update-v2.json</code> (the OTA manifests).</td></tr><tr><td><code>docs/</code></td><td>The documentation tree (below).</td></tr><tr><td><code>tools/</code></td><td>117 build/test/maintenance files (below).</td></tr><tr><td><code>tests/</code></td><td>48 host-side test files (below).</td></tr><tr><td><code>.github/workflows/build.yml</code></td><td>CI: builds the full WP-13 pipeline (<code>make all</code>) under the zero-warning gate (<code>-Wall -Wextra -Werror</code>, enforced by every component&#39;s makefile), verifies the artifacts, and checks <code>make clean</code> leaves nothing behind.</td></tr></tbody></table><h2 id="docs-the-documentation-tree" tabindex="-1"><code>docs/</code> - the documentation tree <a class="header-anchor" href="#docs-the-documentation-tree" aria-label="Permalink to &quot;`docs/` - the documentation tree&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subtree</th><th>Content</th></tr></thead><tbody><tr><td><code>docs/arch/</code></td><td>This set: system-level deep dives (the page you are reading, plus <a href="./boot-flow.html">boot-flow.md</a>, <a href="./memory.html">memory.md</a>, <a href="./scheduler.html">scheduler.md</a>, <a href="./interrupts.html">interrupts.md</a>, <a href="./syscall-ring3.html">syscall-ring3.md</a>, <a href="./vfs.html">vfs.md</a>, <a href="./network-stack.html">network-stack.md</a>, <a href="./driver-model.html">driver-model.md</a>, <a href="./tui-engine.html">tui-engine.md</a>, <a href="./chinese-layer.html">chinese-layer.md</a>, <a href="./crash-recovery.html">crash-recovery.md</a>, <a href="./ota-ab.html">ota-ab.md</a>, <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>, <a href="./private-headers.html">private-headers.md</a>).</td></tr><tr><td><code>docs/l1/</code></td><td>The ring-3 developer view: <code>overview.md</code>, <code>writing-apps.md</code>, <code>app-anatomy.md</code>, <code>surface-map.md</code>, <code>wizard-library.md</code>, <code>solib-loader.md</code>, per-domain driver guides, <code>watchdog-health.md</code>, <code>ota.md</code>, <code>tui-ext.md</code>.</td></tr><tr><td><code>docs/drivers/</code></td><td>Per-family driver pages: <code>pci-pcie.md</code>, <code>acpi.md</code>, <code>storage.md</code>, <code>network.md</code>, <code>wireless.md</code>, <code>usb.md</code>, <code>sound.md</code>, <code>input.md</code>, <code>i2c-smbus.md</code>, <code>time.md</code>, <code>bluetooth.md</code>, <code>sd-camera.md</code>, <code>misc-scsi.md</code>, <code>display.md</code>.</td></tr><tr><td><code>docs/internals/</code></td><td>Mechanism monographs: <code>klog.md</code>, <code>crash-dump.md</code>, <code>watchdog.md</code>, <code>health.md</code>, <code>ota-ab.md</code>, <code>drbg-crypto.md</code>.</td></tr><tr><td><code>docs/manual/</code></td><td>User manual (+ one page per command under <code>commands/</code>), including <code>boot-modes.md</code> and <code>recovery.md</code> which mirror the arch pages from the user side.</td></tr><tr><td><code>docs/dev/</code></td><td>Contributor docs: <code>build.md</code>, <code>environment.md</code>, <code>coding-style.md</code>, <code>portability.md</code>, <code>host-tests.md</code>, <code>e2e-suites.md</code>, <code>qemu-testing.md</code>, <code>debugging.md</code>, <code>pr-workflow.md</code>, <code>ocire.md</code>.</td></tr><tr><td><code>docs/release/</code></td><td>Release process, versioning, per-release notes, website-update and wiki-sync runbooks.</td></tr><tr><td><code>docs/troubleshooting/</code></td><td>Symptom-driven pages: boot failures, QEMU debugging, network/storage/common errors.</td></tr><tr><td><code>docs/root/</code></td><td>Copies of the root-level documents that ship inside images.</td></tr><tr><td><code>docs/archive/</code></td><td>The historical EXTENSIONS_WP*.md work-package reports and CONFIG/STATUS snapshots - the paper trail of how the tree got here. A few internal-environment records (work logs, packaging/verification runbooks) were relocated to the maintainers&#39; internal archive during the 3.0.0 docs cleanup.</td></tr><tr><td><code>docs/data/</code></td><td>Machine-generated doc inputs: <code>stats.json</code> (per-directory line counts), <code>commands.json</code>, <code>interfaces.json</code> - produced by <code>tools/gen_api_docs.py</code> (<code>make api-docs</code>).</td></tr><tr><td><code>docs/zh/</code></td><td>A full Chinese mirror of manual/arch/l1/internals/troubleshooting.</td></tr></tbody></table><h2 id="ocos-the-main-system" tabindex="-1"><code>ocos/</code> - the main system <a class="header-anchor" href="#ocos-the-main-system" aria-label="Permalink to &quot;`ocos/` - the main system&quot;">​</a></h2><h3 id="ocos-kernel-the-l0-core-flat-55-entries-arch-generated" tabindex="-1"><code>ocos/kernel/</code> - the L0 core (flat, 55 entries + <code>arch/</code> + <code>generated/</code>) <a class="header-anchor" href="#ocos-kernel-the-l0-core-flat-55-entries-arch-generated" aria-label="Permalink to &quot;`ocos/kernel/` - the L0 core (flat, 55 entries + `arch/` + `generated/`)&quot;">​</a></h3><p>Naming law: every file is <code>core_&lt;area&gt;_&lt;name&gt;.(c|h)</code> in one flat directory - the historical <code>kernel/core/</code>, <code>kernel/mem/</code>, <code>kernel/lib/</code> paths survive only in &quot;File:&quot; header comments. The areas:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Files</th><th>What the area owns</th></tr></thead><tbody><tr><td><code>core_boot_*</code></td><td><code>entry.S</code>, <code>longmode.S</code>, <code>mb2header.S</code>, <code>main.c</code> (751 lines, the kmain composition root), <code>state.c</code> (boot-state monitor, kernel side), <code>grubstub.c</code>/<code>grubdata.h</code> (two-stage GRUB embed), <code>selftest.c</code> (L1 extension canary), <code>l1launch.c</code> (spawns ush)</td><td>Boot: multiboot2 entry, 32-&gt;64 transition, the hand-curated bring-up sequence</td></tr><tr><td><code>core_mm_*</code></td><td><code>pmm.c</code> (bitmap PMM), <code>vmm.c</code> (4-level page tables), <code>heap.c</code> (free-list heap)</td><td>Memory management - <a href="./memory.html">memory.md</a></td></tr><tr><td><code>core_sched.c</code></td><td></td><td>32-slot preemptive priority+RR scheduler - <a href="./scheduler.html">scheduler.md</a></td></tr><tr><td><code>core_sync.c</code></td><td></td><td>spinlock/semaphore/mutex/condvar</td></tr><tr><td><code>core_timer.c</code></td><td></td><td>PIT @ 100 Hz, ms tick, 16-slot soft timers</td></tr><tr><td><code>core_usermode.c</code></td><td></td><td>syscall table + <code>int 0x80</code> dispatch, ELF64 loader (static + ET_DYN + ASLR), fork, signals, unified reaper - <a href="./syscall-ring3.html">syscall-ring3.md</a></td></tr><tr><td><code>core_kcap.c</code></td><td></td><td>kernel output capture - THE load-bearing path of the L1SVC text surface (<a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>)</td></tr><tr><td><code>core_registry.c</code></td><td></td><td>the <code>.oc_apps</code> L1-application registry collector</td></tr><tr><td><code>core_console_*</code></td><td><code>fb.c</code>, <code>font.c</code>, <code>font_data.c</code> (generated by <code>tools/gen_font.py</code>), <code>screen.c</code></td><td>framebuffer primitives, 8x16 font, text-grid console with the single output-hook slot</td></tr><tr><td><code>core_lib_*</code></td><td><code>config.c</code> (/etc/opencube.conf store), <code>gzip.c</code> (RFC 1951/1952 inflate), <code>i18n.c</code>+<code>i18n_data.c</code> (L0 i18n), <code>klog.c</code> (4-channel kernel log), <code>log.c</code> (boot stage logger), <code>string.c</code>, <code>tar.c</code></td><td>the freestanding runtime library</td></tr><tr><td>generated</td><td><code>userprogs_data.h</code> (27k lines: <strong>284 gzip&#39;d ring-3 programs</strong> + the <code>OC_USERPROGS[]</code> registry, from <code>tools/gen_userprogs.py</code>), <code>solib_data.h</code> (embedded ld.so + libfoo.so),</td><td>the build&#39;s generated payload</td></tr></tbody></table><p><code>ocos/kernel/arch/x86_64/</code> is the real architecture: <code>arch_idt.*</code>, <code>arch_exceptions.*</code>, <code>arch_irq.*</code>, <code>arch_lapic.*</code>, <code>arch_pic.h</code>, <code>arch_multiboot2.*</code>, <code>arch_context_switch.S</code>, <code>arch_enter_ring3_fork.S</code>, <code>arch_exc_exit.S</code> (the IST2 exit stack), <code>arch_abi_probe.S</code>, <code>arch_acpi_s3*.S</code>, <code>linker.ld</code> (with the <code>.oc_drvs/.oc_svcs/.oc_apps</code> section boundaries and the <code>__end_of_kernel &lt;= 0x400000</code> ASSERT). <code>arch/riscv/</code> and <code>arch/arm64/</code> are WP-13 bring-up shells (UART banner + WFI heartbeat, parks secondary harts) - not full kernels, honestly labeled. <code>kernel/generated/</code> holds <code>version_gen.h</code> (the <code>OC_VERSION_STAMP</code> recompile trigger), <code>config_gen.h</code> (the <code>OC_CONFIG_NVME/AHCI/VIRTIO_BLK</code> WP-13 config gate) and <code>grub_boot_data.c</code> (the 1 MB embedded GRUB stage-2 payload).</p><h3 id="ocos-drivers-11-entries-9-class-folders-the-framework-pair" tabindex="-1"><code>ocos/drivers/</code> - 11 entries: 9 class folders + the framework pair <a class="header-anchor" href="#ocos-drivers-11-entries-9-class-folders-the-framework-pair" aria-label="Permalink to &quot;`ocos/drivers/` - 11 entries: 9 class folders + the framework pair&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Folder</th><th>Families declared inside (via <code>OC_DRIVER_DECL</code>)</th></tr></thead><tbody><tr><td><code>drv_framework.{c,h}</code></td><td>The self-registration mechanism itself: the <code>.oc_drvs</code> linker section, <code>drv_framework_collect()</code> into a 256-slot table - <a href="./driver-model.html">driver-model.md</a></td></tr><tr><td><code>storage/</code></td><td>block: <code>ata</code>, <code>ata_dma</code>, <code>ahci</code>, <code>nvme</code>, <code>virtio_blk</code>, <code>scsi</code> (+ SDHCI host + the LSI 53C895A backend)</td></tr><tr><td><code>net/</code></td><td>nic: <code>e1000e</code>, <code>igb</code>, <code>ixgbe</code>, <code>rtl8168</code>, <code>rtl8125</code>, <code>rtl810x</code>, <code>rtl8139</code>, <code>bcm57xx</code>, <code>other</code>; wireless: <code>iwlwifi</code>, <code>ath9k/10k/11k</code>, <code>b43</code>/<code>brcmfmac</code>, <code>rtlwifi</code>; sdio: <code>brcmfmac-sdio</code></td></tr><tr><td><code>usb/</code></td><td>usb: <code>hid-kbd</code>, <code>hid-mouse</code>, <code>usb-msc</code>, <code>cdc-acm</code>, <code>ftdi-serial</code>, <code>usb-audio</code>; the four host controllers (UHCI/OHCI/EHCI/XHCI) live here too</td></tr><tr><td><code>audio/</code></td><td>snd: <code>hda</code>, <code>ac97</code>, <code>es1370</code>, <code>sb16</code>, <code>virtio</code></td></tr><tr><td><code>bus/</code></td><td>PCI/PCIe (CF8/CFC + ECAM + MSI/MSI-X), ACPI (+ the 2077-line AML interpreter), i2c/i801/smbus/DesignWare</td></tr><tr><td><code>input/</code></td><td>PS/2 keyboard, COM1 serial RX bridge (with the ANSI CSI decoder), i2c-hid touchpad</td></tr><tr><td><code>time/</code></td><td>HPET, TSC, ACPI PM timer, CMOS RTC (the PIT lives in the kernel core)</td></tr><tr><td><code>misc/</code></td><td>Bluetooth stack (HCI/H4/USB + L2CAP/RFCOMM/SDP/SPP/HID), camera core + UVC + MJPEG decoder, IR (NEC/RC-5/RC-6/SIRC), parallel port, gameport, and <code>drv_misc_placeholder.c</code> - the deliberate live test of the registration mechanism</td></tr><tr><td><code>display/</code></td><td>a README marker only: the NAK slot reserved for future GPU drivers (the current display pipeline is the firmware-framebuffer console in <code>ocos/kernel/core_console_*</code>)</td></tr></tbody></table><h3 id="ocos-services-24-families-svc-framework-c-h" tabindex="-1"><code>ocos/services/</code> - 24 families + <code>svc_framework.{c,h}</code> <a class="header-anchor" href="#ocos-services-24-families-svc-framework-c-h" aria-label="Permalink to &quot;`ocos/services/` - 24 families + `svc_framework.{c,h}`&quot;">​</a></h3><p>Each folder owns one L1SVC category (or is a kernel-only mechanism owner). The framework (<code>OC_SERVICE_DECL</code>/<code>OC_SERVICE_DECL_L1</code> placing descriptors into <code>.oc_svcs</code>, <code>svc_framework_collect()</code> into a 64-entry table) is documented in <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>; the full category/op numbering is <a href="./syscall-ring3.html">syscall-ring3.md</a>. Families and their categories: <code>time</code>(1), <code>block</code>(2), <code>net</code>(8) + <code>nic</code>(3), <code>audio</code>-&gt;<code>snd</code>(4), <code>power</code>(5), <code>selfhost</code>-&gt;<code>ota</code>(6), <code>fs</code>(7), <code>health</code>(9), <code>klog</code>(10), <code>watchdog</code>(11), <code>crypto</code>(12), <code>l1</code>(13), <code>display</code>(14) + <code>input</code>(15), <code>camera</code>(16), <code>usb</code>(17), <code>ocembed</code>-&gt;<code>ocire</code>(18), <code>diag</code>(19), <code>tui</code>(20) - plus the kernel-only mechanism owners <code>crash</code>, <code>encoding</code>, <code>font</code>, <code>ipc</code>, <code>loader</code>, <code>sysapi</code>. 220 files, ~67k lines; the ring-3 surface totals 208 ops over 20 categories.</p><h3 id="ocos-interface-the-8-private-ring-3-headers" tabindex="-1"><code>ocos/interface/</code> - the 8 private ring-3 headers <a class="header-anchor" href="#ocos-interface-the-8-private-ring-3-headers" aria-label="Permalink to &quot;`ocos/interface/` - the 8 private ring-3 headers&quot;">​</a></h3><p><code>crt0.asm</code>, <code>oc_l1_api.h</code>, <code>l1_lib.h</code>, <code>l1svc_ops.h</code>, <code>fs_lib.h</code>, <code>i18n.h</code>, <code>wizard_lib.h</code>, <code>editor_core.h</code> - the ONLY header set a ring-3 application may include (enforced at build time by the L1 compile <code>-I</code> path). Dedicated page: <a href="./private-headers.html">private-headers.md</a>.</p><h3 id="ocos-l1apps-284-embedded-ring-3-programs" tabindex="-1"><code>ocos/l1apps/</code> - 284 embedded ring-3 programs <a class="header-anchor" href="#ocos-l1apps-284-embedded-ring-3-programs" aria-label="Permalink to &quot;`ocos/l1apps/` - 284 embedded ring-3 programs&quot;">​</a></h3><p>One command = one app = one folder with a <code>main.c</code> + <code>i18n/{en,zh}.json</code> (252 folders, of which <code>_i18n/</code> holds shared tables; the registry count is <code>OC_USERPROGS_COUNT = 284</code>). Categories visible in the tree: the <code>ush</code> shell and its builtins; per-device status commands (<code>ahci</code>, <code>hda</code>, <code>e1000e</code>, <code>wifi</code>...); the <code>*_test</code> batteries (50+); the 8 merged mega-apps (<code>update</code>, <code>disk-tool</code>, <code>net-tool</code>, <code>sound-tool</code>, <code>files</code>, <code>sysdiag</code>, <code>hwinfo</code>, <code>power</code>) built on <code>wizard_lib.h</code>; the editors (<code>nano</code>, <code>vi</code>, <code>edit</code> sharing <code>editor_core.h</code>); text tools (<code>cat</code>, <code>grep</code>, <code>sed</code>, <code>awk</code>, <code>sort</code>, <code>wc</code>...). Plus ~34 flat top-level sources: the legacy <code>.asm</code> test programs (<code>fork_test.asm</code>, <code>g6_*.asm</code>, ...), the dynamic-link test set (<code>ld_so.c</code>, <code>libfoo.c</code>, <code>main_dyn.c</code>, <code>pie_test.c</code>) and <code>user.ld</code> (the ring-3 link script, load address 0x400000). Why one folder per app: <code>tools/gen_userprogs.py</code> walks the tree, compiles each folder against <code>ocos/interface/</code> only, gzip-compresses the ELF and appends it to <code>userprogs_data.h</code> with a bilingual hint (<a href="./hidden-mechanisms.html">hidden-mechanisms.md</a> explains the lazy inflate; <a href="./../l1/app-anatomy.html">../l1/app-anatomy.md</a> the app shape).</p><h2 id="ocbl-the-boot-loader-59-files" tabindex="-1"><code>ocbl/</code> - the boot loader (59 files) <a class="header-anchor" href="#ocbl-the-boot-loader-59-files" aria-label="Permalink to &quot;`ocbl/` - the boot loader (59 files)&quot;">​</a></h2><p>Three backends around one firmware-agnostic core:</p><table tabindex="0"><thead><tr><th>Folder</th><th>Files</th><th>Content</th></tr></thead><tbody><tr><td><code>bios/</code></td><td>16</td><td><code>stage1.asm</code> (the 512-byte sector, two flavors from one source: <code>-D OCBL_ELTORITO</code> / <code>-D OCBL_MBR</code>), <code>core_head.S</code> (32-&gt;64 core entry, identity page tables at 0x8F000, EBDA guard), the real-mode trampoline pair, int 10h/13h/14h/15h/16h/1Ah backends, VBE, RSDP scan, VBR chainload</td></tr><tr><td><code>efi/</code></td><td>10</td><td>the freestanding UEFI type definitions (no EDK2), <code>efi_entry.c</code> (MS-ABI entry, fixed-window reserves, EBS retry loop), BlockIo disk backend, GOP, GetMemoryMap-&gt;E820, EFI chainload, the 64-&gt;32 handoff blob</td></tr><tr><td><code>common/</code></td><td>23</td><td>the six-class scanner, the read-only FAT12/16/32+ISO9660 volume layer, MBR/GPT traversal (incl. the 0xEE shadow case), the ELF loader + mb2 builder, the 3-key menu, the boot-state monitor, ACPI S5, the 6300ESB watchdog, polled 16550 serial, and the flavor contract headers</td></tr></tbody></table><p>Top level: <code>ocbl.mk</code> (all make targets), <code>linker_bios.ld</code> (core at 0x7E00), <code>linker_efi.ld</code> (intermediate ELF at 0x11000), and the Python build pack: <code>build_image.py</code>, <code>build_test_iso.py</code> (the ISO packer for ALL ISOs - dual El Torito, G13 determinism, deliberately no <code>-boot-info-table</code>), <code>elf_to_efi.py</code>, <code>make_scan_disks.py</code> (the 8-image scanner test fleet), <code>make_chain_disks.py</code>, <code>menu_drive.py</code> (QEMU monitor sendkey driver), <code>qemu_snap.py</code>. Deep dive: <a href="./boot-flow.html">boot-flow.md</a>.</p><h2 id="ocire-the-recovery-kernel-49-files" tabindex="-1"><code>ocire/</code> - the recovery kernel (49 files) <a class="header-anchor" href="#ocire-the-recovery-kernel-49-files" aria-label="Permalink to &quot;`ocire/` - the recovery kernel (49 files)&quot;">​</a></h2><p>A flat source tree (own everything: <code>ocire_ata.c</code>, <code>ocire_fat.c</code>, <code>ocire_sha256.c</code>, <code>ocire_console.c</code>, <code>ocire_idt.c</code>, <code>ocire_acpi.c</code>, <code>ocire_wdt.c</code>, ...) plus three special corners:</p><ul><li><code>ocire/agent/ocire_agent.c</code> - the ring-3 log agent, compiled like an l1apps program (freestanding + <code>ocos/l1apps/user.ld</code> @ 0x400000 + <code>int 0x80</code>), shipped as a standalone ELF on the recovery volume and injected at kexec as the protected <code>ocire_guard</code> process. It lives in its own subfolder because it is the one OCIRE file that builds against the OCOS ABI.</li><li><code>ocire/generated/</code> - <code>ocire_version_gen.h</code> (the <code>OCIRE_STAMP</code> banner) and <code>ocire_cn_font_data.c</code> (generated from OCSE&#39;s font data by a sed include-rewrite rule, so font re-vendorings flow in automatically).</li><li><code>ocire/grub-dual.cfg.in</code> - the template for the one remaining GRUB chain (the dual-boot repair-target disk), with <code>@KERN_LBA@</code>/ <code>@KERN_SECTORS@</code> blocklist placeholders filled by <code>tools/make_ocire_disk.sh</code>.</li></ul><p>Plus <code>ocire_bootsvc.c</code> (the supervisor decision loop), <code>ocire_kexec.c</code> + <code>ocire_kexec_jump.S</code> (the OCOS re-launch), <code>ocire_shell.c</code> / <code>ocire_recover.c</code> (the bilingual recovery shell: <code>logread</code>, <code>syscheck</code> ten-point integrity check, <code>repair quick|full</code>, <code>return</code>, <code>shutdown</code>, <code>reboot</code>, <code>lang</code>). Deep dive: <a href="./../dev/ocire.html">../dev/ocire.md</a> and <a href="./crash-recovery.html">crash-recovery.md</a>.</p><h2 id="ocse-the-install-environment-179-files" tabindex="-1"><code>ocse/</code> - the install environment (179 files) <a class="header-anchor" href="#ocse-the-install-environment-179-files" aria-label="Permalink to &quot;`ocse/` - the install environment (179 files)&quot;">​</a></h2><p><strong>Vendored from git tag v1.0.0</strong> (commit bdc47047, the last pre-restructure monolithic kernel - 143 vendored files under <code>ocse/{kernel,drivers,fs,l1,boot,chinese}</code>). Why vendored: OCSE runs before any OCOS service exists, v1.0.0 already contained every driver an installer needs, and a frozen copy keeps the installer bootable as the main kernel evolves. The re-vendor + patch loop: <code>tools/vendor_ocse.sh</code> (PRESERVE list keeps OCSE-native files like the PS/2 mouse driver) + <code>tools/ocse_edits.py</code> (edits <strong>E1-E20</strong>, the only sanctioned way the vendored base changes - never hand-edit <code>ocse/{kernel,drivers,fs,l1,boot,chinese}/*.c</code>). The edits strip what an installer must not have: E1 OTA/update API, E4/E5/E6 ring-3 crash/kill/int 0x80 (no user plane), E7 USB MSC/serial pollers, E12 replaces the OC_DRIVER_DECL collection with direct calls from the 24-stage boot ladder. On top of the vendored base sit the OCSE-native pieces: <code>ocse_main.c</code> (mode loop GUI&lt;-&gt;CLI), <code>ocse_cl.c</code> (OCSECL, 1919 lines, 40 commands), <code>ocse_gui.c</code> + <code>ocse_wizard.c</code> + <code>ocse_wzctl.c</code> (the 9-step wizard + widget toolkit), <code>ocse_inst.c</code> (the installer engine: OCBL MBR writer + the 8-step install state machine), <code>ocse_mkfs.c</code> / <code>ocse_ext4w.c</code> (real FAT32/exFAT/ext4 formatters, ext4 even writable), <code>ocse_atapi.c</code> / <code>ocse_iso.c</code> (the install medium), <code>ocse_detect.c</code> (the four hardware checks), <code>ocse_i18n.c</code>, and <code>linker_ocse.ld</code> (1 MiB base, the <code>.ocsework</code> NOLOAD wizard-state zone, the same 0x400000 ASSERT). <a href="./boot-flow.html">boot-flow.md</a> covers the handoff; the E1-E20 list is <code>ocse/VENDORING.md</code>.</p><h2 id="tools-117-files" tabindex="-1"><code>tools/</code> - 117 files <a class="header-anchor" href="#tools-117-files" aria-label="Permalink to &quot;`tools/` - 117 files&quot;">​</a></h2><p>Roughly six tribes:</p><table tabindex="0"><thead><tr><th>Tribe</th><th>Examples</th><th>Purpose</th></tr></thead><tbody><tr><td>Build &amp; packaging</td><td><code>build.sh</code>, <code>build_iso.sh</code>, <code>build_ocse_iso.sh</code>, <code>build_ocire_iso.sh</code>, <code>build_release.sh</code>, <code>install-toolchain.sh</code>, <code>oc_cc.sh</code>, <code>env-sandbox.sh</code>, <code>oc_menuconfig.sh</code>, <code>make_ab_disk.sh</code>, <code>make_ocire_disk.sh</code>, <code>make_ocos_tar.py</code>, <code>make_update_pkg.sh</code>, <code>make_wdat_table.py</code>, <code>iso_zero_ctime.py</code>, <code>fat_zero_dates.py</code></td><td>The WP-13 pipeline from a clean tree to a signed-shape ISO + OTA package; determinism shims (zeroed timestamps)</td></tr><tr><td>Embedders</td><td><code>embed_grub.py</code> (GRUB boot.img+core.img into the kernel), <code>embed_roots.py</code> (CA roots -&gt; crypto), <code>embed_userprog.py</code>, <code>build_solib.py</code>, <code>build_c_userprog.py</code></td><td>Everything the kernel ships inside its image</td></tr><tr><td>Generators</td><td><code>gen_userprogs.py</code> (the 284-app registry), <code>gen_font.py</code> / <code>gen_font_gz.py</code> / <code>gen_chinese_font.py</code>, <code>gen_pinyin_phrase.py</code>, <code>gen_l0_i18n.py</code>, <code>gen_l1svc_ops.py</code> (the frozen ABI mirror - <a href="./private-headers.html">private-headers.md</a>), <code>gen_api_docs.py</code> (docs/data/*.json), <code>gen_svc_api_headers.py</code>, <code>gen_gzip_vectors.py</code>, <code>apply_i18n_hints.py</code> / <code>apply_tool_i18n.py</code></td><td>Turn source data into compiled-in tables</td></tr><tr><td>E2E drivers</td><td><code>wp01_*</code> .. <code>wp12_*</code>, <code>p0*</code>, <code>fix1_*</code>, <code>run_ocire_*</code>, <code>run_l1_per_app.py</code>, <code>wp10_native_e2e.py</code>, <code>wp12_watchdog_logging_e2e.py</code>, ...</td><td>QEMU batteries that boot real images and grep serial transcripts (the acceptance methodology)</td></tr><tr><td>Peers &amp; servers</td><td><code>https_test_server.py</code>, <code>p0_evil_tls_server.py</code>, <code>p0_redir_server.py</code>, <code>paramiko_sshd.py</code>, <code>ssh_g11a_e2e.py</code>, <code>bt_test_peer.py</code>, <code>update_server.py</code>, <code>qemu_runner.py</code>, <code>qemu_shot.py</code> / <code>qemu_shot_vnc.py</code></td><td>The other side of the wire for network tests; QEMU plumbing</td></tr><tr><td>Maintenance &amp; restructure</td><td><code>nak_migrate.py</code> / <code>nak_fix_refs.py</code> / <code>nak_map.tsv</code> / <code>restructure_*.py</code> (5), <code>fix_file_headers.py</code>, <code>check_bss.py</code>, <code>check_deps.py</code>, <code>v2_registry_gate.py</code>, <code>sync_wiki.sh</code>, <code>update_website.sh</code>, <code>github_release_wp08.sh</code>, host C tests (<code>host_gzip_test.c</code>, <code>ocire_fat_host_test.c</code>), data (<code>ime_phrases.txt</code>, <code>update_test_vectors.h</code>)</td><td>The scripts that keep a 150k-line tree honest</td></tr></tbody></table><h2 id="tests-48-files" tabindex="-1"><code>tests/</code> - 48 files <a class="header-anchor" href="#tests-48-files" aria-label="Permalink to &quot;`tests/` - 48 files&quot;">​</a></h2><ul><li><strong>25 <code>host_*.c</code> files</strong> - host-compiled unit tests for kernel code that is pure enough to link off-target: <code>host_mb2_test.c</code> (multiboot2 parser), <code>host_tls13_ks_test.c</code>, <code>host_x25519_test.c</code>, <code>host_bn_ec_test.c</code>, <code>host_aead_test.c</code>, <code>host_rsa_test.c</code>, <code>host_x509_test.c</code>, <code>host_tcpcc_test.c</code> (CUBIC), <code>host_fix4_tar_test.c</code> / <code>host_fix4_crypto_test.c</code>, <code>host_scsi_test.c</code>, <code>host_camera_test.c</code> (MJPEG decoder vs double-precision reference), <code>host_ir_test.c</code>, <code>host_i2chid_touch_test.c</code>, <code>host_wifi_test.c</code>, <code>host_bt_test.c</code>, <code>host_gcm_probe.c</code>, plus stubs (<code>host_registry_stub.c</code>, <code>host_pmm_stub.c</code>, ...). Run by <code>tools/run_host_tests.py</code>; the discipline is documented in <a href="./../dev/host-tests.html">../dev/host-tests.md</a>.</li><li><strong>23 Python batteries</strong> - the OCSE/installer and i18n QEMU acceptance suites: <code>ocse_t1_neg.py</code> (the no-disk negative acceptance - check4 FAIL must halt the machine honestly) through <code>ocse_t7_regress.py</code>, <code>ocsecl_b2_part.py</code>..<code>b6_i18n_flow.py</code> (the OCSECL command battery), <code>ocse_w6_gui.py</code> (headless GUI click probe), <code>ocse_wp06f_*</code> (PS/2 probe + fix battery), <code>wp06g1_font_audit.py</code> / <code>wp06g2_*_verify.py</code> (font/IME/i18n/editor verification).</li></ul><p>The in-guest test surface (the other half of the story) is not in <code>tests/</code> at all: it is the 50+ <code>*_test</code> L1 applications under <code>ocos/l1apps/</code> plus the L1SVC diag category&#39;s 39 ops, reachable from a booted system - see <a href="./syscall-ring3.html">syscall-ring3.md</a>.</p>',36)])])}const _=o(r,[["render",a]]);export{p as __pageData,_ as default};
